def icon(name, size=24):
    """SVG иконки Material Symbols нужного размера (сторона = size px)."""
    vb, ds = ICONS[name]
    body = ''.join('<path fill="currentColor" d="%s"/>' % d for d in ds)
    return '<svg viewBox="%s" width="%d" height="%d">%s</svg>' % (vb, size, size, body)
